import{z as r,x as l,o as A,c as d,q as t,j as s,D as a,d as i,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"所得税与激励","description":"","frontmatter":{"title":"所得税与激励","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/income-tax-incentives.md","filePath":"econ/income-tax-incentives.md","lastUpdated":1791413859000}'),p={name:"econ/income-tax-incentives.md"};function m(D,E,c,S,h,u){const n=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="所得税与激励" tabindex="-1">所得税与激励 <a class="header-anchor" href="#所得税与激励" aria-label="Permalink to &quot;所得税与激励&quot;">​</a></h1><div class="epigraph"><p>能力不可观察时，非线性所得税在再分配与劳动供给之间权衡；最优边际税率由弹性、能力密度与社会福利权重共同决定，不是「高税率自动更公平」。</p><footer>—— Mirrlees, Review of Economic Studies 1971；Saez, Using Elasticities to Derive Optimal Income Tax Rates, RES 2001；对照 Atkinson and Stiglitz；Diamond</footer></div><p><a href="/econ/ramsey-optimal-commodity-tax">上一课</a>在代表性消费者下分配商品税楔子。本课缺口是人与人之间的能力差异：要再分配，又不能按能力一次总付，只能按收入（可观察的选择）征税，于是劳动供给被楔子扭曲。Atkinson–Stiglitz 已提示：有了非线性所得税，商品税可能多余。本课把所得税本身写成激励相容的机制。后课把效率代价从公式收到漏桶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>能力 \\(n\\) 私有信息，收入 \\(y=nl\\)，税 \\(T(y)\\)。高能力可以模仿低能力的 \\(y\\) 来少缴税。激励相容迫使边际税率不能随便钉在 100%：顶层若还想让人揭示，边际税有上限（经典 Mirrlees 顶层为零是特殊密度下的结果，应用里被 Saez 用厚尾密度改写）。缺口不是再讲劳动供给曲线，而是：<strong>再分配的导数必须经过行为弹性</strong>，观测到的收入变化含替代、收入与逃税，政策弹性与微观弹性不必相同。</p><p><span class="marginnote">「楔子」就是税率插在「你挣到的」与「你拿到手的」之间那道缝：边际税率 40% 意味着多挣 100 块只到手 60 块——决定你愿不愿意多干一小时的，是这 40 块的缝（边际税率），不是全年缴税总额（平均税率）。两个税率答两道不同的题，混起来就会开错药方。</span></p><p>intensive（已工作的人调时数）与 extensive（是否参与）对最优税率形状不同：底部参与弹性高时，低收入段边际税应低，甚至补贴，以免把人挡在市场外。</p><p><span class="marginnote">intensive 与 extensive 的区别可以代入数字：月薪 2000 的人，若加班每小时到手 12 块，他可能少加几小时（intensive 反应）；但若通勤加托儿每月固定要 800 块、到手的净收入所剩无几，他可能干脆不来上班（extensive 反应）。底部的边际税率要低甚至为负（如 EITC 补贴），正是为了把这 800 块的门槛垫平，先把人拉进市场。</span></p><h3 id="高税率不是自动更再分配" tabindex="-1">高税率不是自动更再分配 <a class="header-anchor" href="#高税率不是自动更再分配" aria-label="Permalink to &quot;高税率不是自动更再分配&quot;">​</a></h3><p>平均税率决定从谁收到谁；边际税率决定扭曲。混淆两者，会把「提高最高档法定税率」当成再分配已经完成，却漏掉申报、避税与收入定义。Saez 把最优边际税写成弹性、密度、福利权重的充分统计公式，让争论落到可估对象，而不是落到口号。</p><p><span class="marginnote">Mirrlees 1971 用道德风险/逆向选择语言：政府看到 \\(y\\) 看不到 \\(n\\)。最优是一连串激励约束下的规划。Saez 2001 把它翻译成弹性语言，便于实证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>充分统计：在所考虑的改革方向上，\\(\\mathrm{d}W\\) 由机械的收入转移、行为造成的税基收缩、以及福利权重组成。报告收入弹性（含避税）比只报工时弹性更接近税基。商品税：若弱可分，非线性所得税已处理能力，Ramsey 商品税的分配角色下降——这是上一课边界的兑现。非线性与线性：线性税只有一个楔子，管理便宜；非线性对准密度形状，顶部与底部可以不同。</p>',13)),(A(),s(o,null,{default:a(()=>[B(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%95%86%E5%93%81%E7%A8%8E%E7%AD%B9%20R%22%5D%20--%3E%20CAP%5B%22%E8%83%BD%E5%8A%9B%E4%B8%8D%E5%8F%AF%E8%A7%82%E5%AF%9F%22%5D%0A%20%20CAP%20--%3E%20MIR%5B%22%E9%9D%9E%E7%BA%BF%E6%80%A7%20T(y)%20%E6%BF%80%E5%8A%B1%E7%9B%B8%E5%AE%B9%22%5D%0A%20%20MIR%20--%3E%20ELAST%5B%22%E5%BC%B9%E6%80%A7%E3%80%81%E5%AF%86%E5%BA%A6%E3%80%81%E7%A6%8F%E5%88%A9%E6%9D%83%E9%87%8D%22%5D%0A%20%20ELAST%20--%3E%20OKUN%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E5%86%8D%E5%88%86%E9%85%8D%E7%9A%84%E6%95%88%E7%8E%87%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"不要把法定税率表当成有效边际税率：扣除、优惠、社保缴款都会改楔子。申报收入弹性把避税通道算进行为，工时弹性会低估税基反应，从而高估最优边际税。跨国把弹性当同一数字更危险：执法与扣除菜单不同，充分统计不可直接搬运。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是显示原理：要让高 \\(n\\) 不模仿低 \\(n\\)，必须留给信息租金，租金表现为较低的边际税或较高的税后消费。弹性越大，同样再分配的税基收缩越狠，最优边际税越低。密度在某段越厚，机械转移越大，越值得在那段加楔子。底部 extensive 弹性把「参与」写成另一条一阶条件，EITC 一类补贴是对准这条，不是对准 Ramsey 商品税。",-1)),E[6]||(E[6]=e("p",null,[e("span",{class:"marginnote"},"初学者容易以为「边际税率越高越再分配」，实际上税率高过某个程度，高能力者会少工作或把收入搬进避税通道，税基缩水后收上来的钱反而更少——Saez 公式里的「弹性」一项，就是这道漏水的阀门。")],-1)),(A(),s(o,null,{default:a(()=>[B(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E7%A4%BE%E4%BC%9A%E7%A6%8F%E5%88%A9%E6%9D%83%E9%87%8D%3A%20%E8%B6%8A%E5%9C%A8%E4%B9%8E%E5%BA%95%E5%B1%82%E8%B6%8A%E9%AB%98%22%5D%20--%3E%20SHAPE%5B%22%E6%9C%80%E4%BC%98%E8%BE%B9%E9%99%85%E7%A8%8E%E7%8E%87%E6%B2%BF%E6%94%B6%E5%85%A5%E5%88%86%E5%B8%83%E7%9A%84%E5%BD%A2%E7%8A%B6%22%5D%0A%20%20E%5B%22%E8%A1%8C%E4%B8%BA%E5%BC%B9%E6%80%A7%3A%20%E5%90%AB%E9%81%BF%E7%A8%8E%2C%20%E8%B6%8A%E5%A4%A7%E6%A5%94%E5%AD%90%E8%B6%8A%E4%BA%8F%22%5D%20--%3E%20SHAPE%0A%20%20D%5B%22%E8%83%BD%E5%8A%9B%E5%AF%86%E5%BA%A6%3A%20%E5%93%AA%E6%AE%B5%E4%BA%BA%E5%A4%9A%E8%B6%8A%E5%80%BC%E5%BE%97%E5%8A%A0%E6%A5%94%22%5D%20--%3E%20SHAPE%0A%20%20SHAPE%20--%3E%20MIDDLE%5B%22%E4%B8%AD%E6%AE%B5%3A%20%E5%AF%86%E5%BA%A6%E5%8E%9A%2C%20%E8%BE%B9%E9%99%85%E7%A8%8E%E8%BE%83%E9%AB%98%22%5D%0A%20%20SHAPE%20--%3E%20BOTTOM%5B%22%E5%BA%95%E9%83%A8%3A%20%E5%8F%82%E4%B8%8E%E5%BC%B9%E6%80%A7%E5%A4%A7%2C%20%E4%BD%8E%E8%BE%B9%E9%99%85%E7%A8%8E%E6%88%96%E8%A1%A5%E8%B4%B4%22%5D%0A%20%20SHAPE%20--%3E%20TOPRATE%5B%22%E9%A1%B6%E9%83%A8%3A%20%E5%AF%86%E5%BA%A6%E8%96%84%E5%BC%B9%E6%80%A7%E5%A4%A7%2C%20%E8%BE%B9%E9%99%85%E7%A8%8E%E4%B8%8D%E5%BF%85%E9%AB%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p>与公共品连接：\\(R\\) 与 \\(G\\) 仍在，但筹资工具从商品篮换到劳动收入。边际公共资金现在含劳动楔子，不只含 Ramsey \\(t_i\\)。夫妻联合申报、资本与劳动的边界，都会改变 \\(y\\) 的定义，从而改变激励相容的对象——本课不写家庭劳动供给全书，只要求：税基定义先于弹性数字。</p><p><span class="marginnote">Diamond 对顶部税率与 Pareto 分布的讨论，以及 Saez 的经验校准，是同一公式的不同密度假设。本课不选定某一个「最优顶税率数字」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估一套国家税率表，不写申报软件。资本税、动态 Mirrlees 不在此展开。逃税作为弹性的一部分点到，不写稽查博弈。下一课把「弹性造成的漏」收成再分配与效率的权衡语言，接到 Okun 与 Atkinson。后课默认：谈所得税先分清平均与边际、intensive 与 extensive，并用弹性而不是法定档次读激励。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>能力不可观察，所得税必须激励相容，边际税扭曲劳动。</li><li>最优边际税由弹性、密度、福利权重决定。</li><li>高法定税率不等于再分配完成；有效楔子与税基弹性才算。</li><li>底部参与弹性指向低收入段低边际税或补贴。</li><li>出处：Mirrlees, <em>RES</em> 1971；Saez, <em>RES</em> 2001；Atkinson and Stiglitz；Diamond。</li></ul>',6))])}const x=r(p,[["render",m]]);export{f as __pageData,x as default};
